import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Color, Vector3 } = ctx.THREE;
  const group = new Group();

  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // 1. STAGE: Build backdrop plane to prevent flat void
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Clean gradient using TSL
  const topColorObj = colors.ink;
  const bottomColorObj = colors.surface;
  const topColor = vec3(topColorObj.r, topColorObj.g, topColorObj.b);
  const bottomColor = vec3(bottomColorObj.r, bottomColorObj.g, bottomColorObj.b);
  backdropMat.colorNode = mix(bottomColor, topColor, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  // 2. HERO CARD (Plane carrying the image)
  const cardGeo = new PlaneGeometry(3.6, 2.25); // 1.6:1 ratio match to 512x320
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0 // Start at 0 for GSAP fade-in
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0.3, 0);
  group.add(cardMesh);

  // Load Image Asset via Loader
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    cardMat.colorNode = texture;
    cardMat.needsUpdate = true;
    gsap.to(cardMat, { opacity: 1.0, duration: 0.6, ease: 'power2.out' });
  }).catch((err) => {
    // Fallback if texture fails: clean engineered metal style
    cardMat.colorNode = mix(vec3(0.09, 0.09, 0.12), vec3(0.15, 0.15, 0.2), uv().y);
    gsap.to(cardMat, { opacity: 1.0, duration: 0.4 });
  });

  // 3. TEXT CONTENT (Rendered using font atlas)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(0, -1.1, 0.1);
  group.add(textGroup);

  let textStr = "A machined-metal watch atelier landing with catalog, pricing, jo";
  if (items.length > 0) {
    textStr = items[0].text;
  }

  // Mono style for the tagline per-spec
  const labelText = ctx.fontAtlas.createText(textStr, {
    fontSize: 0.14,
    color: '#e8ecf2', // Paper color
    align: 'center',
    maxWidthPx: 800
  });
  textGroup.add(labelText);

  // 4. ANIMATION: Simple weighted rise-in entrance on load
  group.position.y += 0.3;
  const tl = gsap.timeline();
  tl.to(group.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  });

  // 5. CLEANUP
  group.userData = {
    handlers: {},
    cleanup: () => {
      tl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
    }
  };

  return group;
}
